-- 2.15.0: nutrition facts of the recipes (calories, Nutri-Score), from the Ciqual table of the Anses.

-- The foods of the Ciqual table (Anses, Licence Ouverte Etalab 2.0), per 100 g: those of the version 2025 below,
-- replaced by the admin when importing a new version (Ingrédients, "Table Ciqual"). A constituent the table
-- does not give is null; "traces" and "< x" are taken as 0. Proteins: N x 6.25, as on the labels.
CREATE TABLE ciqual_food (
    code          integer PRIMARY KEY CHECK (code > 0),
    name          text    NOT NULL CHECK (char_length(name) BETWEEN 1 AND 300),
    subgroup_code text    NOT NULL CHECK (subgroup_code ~ '^[0-9]{4}$'),
    subgroup_name text    CHECK (char_length(subgroup_name) <= 200),
    kcal          numeric(9, 3) CHECK (kcal >= 0),
    proteins      numeric(9, 3) CHECK (proteins >= 0),
    carbohydrates numeric(9, 3) CHECK (carbohydrates >= 0),
    sugars        numeric(9, 3) CHECK (sugars >= 0),
    fat           numeric(9, 3) CHECK (fat >= 0),
    saturated_fat numeric(9, 3) CHECK (saturated_fat >= 0),
    fibre         numeric(9, 3) CHECK (fibre >= 0),
    salt          numeric(9, 3) CHECK (salt >= 0)
);

-- The version of the Ciqual table in ciqual_food, named in the source shown under the nutrition facts. One row.
CREATE TABLE ciqual_table (
    id          smallint    PRIMARY KEY DEFAULT 1 CHECK (id = 1),
    version     text        NOT NULL CHECK (char_length(version) BETWEEN 1 AND 100),
    food_count  integer     NOT NULL CHECK (food_count >= 0),
    imported_at timestamptz NOT NULL,
    imported_by text        NOT NULL
);


-- The nutrition facts of an ingredient: the Ciqual food it is, or the values of its label (whey, a product of a
-- brand…), per 100 g; one or the other, or none yet. label_source: where the label comes from, "Open Food Facts ·
-- Kinder Bueno · Ferrero · 3017626998106", null when typed by the admin. A food that leaves the table with a new
-- version leaves the ingredients too: they are to be linked again.
ALTER TABLE ingredient
    ADD COLUMN ciqual_code         integer REFERENCES ciqual_food (code) ON DELETE SET NULL,
    ADD COLUMN label_kcal          numeric(6, 1) CHECK (label_kcal BETWEEN 0 AND 950),
    ADD COLUMN label_proteins      numeric(5, 2) CHECK (label_proteins BETWEEN 0 AND 100),
    ADD COLUMN label_carbohydrates numeric(5, 2) CHECK (label_carbohydrates BETWEEN 0 AND 100),
    ADD COLUMN label_sugars        numeric(5, 2) CHECK (label_sugars BETWEEN 0 AND 100),
    ADD COLUMN label_fat           numeric(5, 2) CHECK (label_fat BETWEEN 0 AND 100),
    ADD COLUMN label_saturated_fat numeric(5, 2) CHECK (label_saturated_fat BETWEEN 0 AND 100),
    ADD COLUMN label_fibre         numeric(5, 2) CHECK (label_fibre BETWEEN 0 AND 100),
    ADD COLUMN label_salt          numeric(5, 2) CHECK (label_salt BETWEEN 0 AND 100),
    ADD COLUMN label_source        text CHECK (char_length(label_source) BETWEEN 1 AND 300),
    ADD CONSTRAINT ingredient_label_source CHECK (label_source IS NULL OR label_kcal IS NOT NULL),
    ADD CONSTRAINT ingredient_label_complete CHECK (
        (label_kcal IS NULL) = (label_proteins IS NULL) AND (label_kcal IS NULL) = (label_carbohydrates IS NULL)
        AND (label_kcal IS NULL) = (label_sugars IS NULL) AND (label_kcal IS NULL) = (label_fat IS NULL)
        AND (label_kcal IS NULL) = (label_saturated_fat IS NULL) AND (label_kcal IS NULL) = (label_fibre IS NULL)
        AND (label_kcal IS NULL) = (label_salt IS NULL)),
    ADD CONSTRAINT ingredient_nutrition_single CHECK (ciqual_code IS NULL OR label_kcal IS NULL);

CREATE INDEX ingredient_ciqual_code_idx ON ingredient (ciqual_code) WHERE ciqual_code IS NOT NULL;

-- Shows the nutrition facts on the page of the recipe, computed from its ingredients.
ALTER TABLE recipe ADD COLUMN show_nutrition boolean NOT NULL DEFAULT false;

-- Ciqual 2025 (3 484 foods), Anses, published on 19/11/2025: https://doi.org/10.57745/RDMHWY
